from produire import produire,paras,table,steps
from medicaments import jorveza
produire(4,[
('L’œsophagite à éosinophiles est une maladie inflammatoire chronique à médiation immunitaire. Les {critères cliniques et tissulaires} doivent être réunis pour le diagnostic.',paras('Elle associe symptômes de dysfonction œsophagienne et infiltration éosinophile de la muqueuse, après évaluation des autres causes possibles. Chez l’adulte, dysphagie et impaction alimentaire sont des présentations importantes.', 'Chez l’enfant, difficultés alimentaires, vomissements, douleurs ou troubles de croissance peuvent prédominer. Un résultat sanguin ou un test allergologique isolé ne remplace pas les biopsies œsophagiennes.')),
('Une atopie et un jeune âge peuvent orienter, mais ne définissent pas la maladie. Le {contexte épidémiologique} ne doit pas devenir un critère d’exclusion.',paras('La maladie est décrite chez l’enfant comme chez l’adulte, souvent avec asthme, rhinite, eczéma ou allergies alimentaires associés. L’absence d’atopie connue ne l’exclut pas.', 'Un retard diagnostique peut favoriser une évolution fibreuse et sténosante. Les adaptations spontanées des repas peuvent masquer longtemps la dysphagie.', 'Aucune proportion suisse parmi l’ensemble des dysphagies n’est attribuée ici. La position dans la liste diagnostique sert la démarche clinique, pas un classement chiffré.')),
('L’inflammation peut entraîner remodelage et fibrose de la paroi. Les {mécanismes complémentaires} expliquent pourquoi élargir l’œsophage ne suffit pas.',paras('Une réponse immunitaire à des antigènes contribue à l’infiltrat éosinophile et aux lésions épithéliales. L’atopie est fréquente, mais les tests d’allergie immédiate ne permettent pas de désigner à eux seuls tous les aliments responsables de l’inflammation œsophagienne.', 'La fibrose réduit la distensibilité et peut produire des anneaux, un rétrécissement diffus ou une sténose. Une impaction peut révéler cette composante mécanique.', 'Le traitement anti-inflammatoire vise l’activité de la maladie. La dilatation corrige une composante obstructive sélectionnée, sans traiter l’inflammation elle-même.')),
('L’impaction alimentaire est une complication urgente. Les {signes de gravité} exigent de traiter l’obstruction avant le suivi inflammatoire.',table(['🚩 Situation','Conduite'],[['Aliment bloqué, salive impossible à avaler.','Urgence endoscopique pour obstruction complète possible.'],['Détresse respiratoire ou étouffement.','Appel au 144 et prise en charge respiratoire immédiate.'],['Douleur thoracique sévère, fièvre, aggravation après vomissement ou procédure.','Évaluation urgente d’une perforation ou autre complication.'],['Amaigrissement, apports insuffisants ou retard de croissance.','Évaluation nutritionnelle et spécialisée rapide.']])) ,
('Les adaptations des repas peuvent minimiser le symptôme déclaré. Les {questions alimentaires} recherchent ce que la personne évite ou compense.',paras('Demander impactions, mastication prolongée, petites bouchées, prise de boisson pour faire passer les aliments et évitement des textures solides. Rechercher durée des repas et impact social.', 'Préciser atopie, allergies connues, croissance ou poids et traitement antérieur. Noter les inhibiteurs de la pompe à protons et les corticoïdes susceptibles de modifier l’histologie.', 'Revoir aussi les immunothérapies allergéniques. Swissmedic signale une œsophagite à éosinophiles possible sous certaines immunothérapies : des symptômes persistants doivent être signalés au prescripteur et explorés.')),
('L’examen apprécie nutrition, hydratation et complications. Les {limites des signes externes} expliquent la nécessité du bilan endoscopique.',paras('Mesurer poids et évolution pondérale, évaluer la croissance chez l’enfant, rechercher déshydratation et restriction alimentaire. Examiner bouche et respiration selon les symptômes.', 'Des manifestations atopiques peuvent être présentes sans prouver le diagnostic. Un examen normal ne permet pas d’exclure une inflammation ou une sténose œsophagienne.', 'Sous corticoïde avalé, une douleur ou gêne nouvelle doit faire envisager notamment une candidose, sans attribuer automatiquement toute récidive à une poussée inflammatoire.')),
('Une éosinophilie œsophagienne n’a pas une cause unique. Les {diagnostics différentiels} se confrontent au contexte et aux prélèvements.',table(['Cause ou mécanisme','Distinction utile'],[['Reflux et sténose peptique.','Peuvent imiter ou coexister avec la maladie.'],['Cancer ou autre obstacle.','Biopsies et bilan selon aspect et signaux d’alarme.'],['Trouble moteur, dont achalasie.','À rechercher si la dysphagie reste inexpliquée après bilan organique.'],['Autres causes locales ou systémiques d’éosinophilie.','Infection, médicament, autre maladie digestive ou syndrome systémique selon contexte.'],['Allergie alimentaire immédiate.','Peut coexister, mais son bilan ne remplace pas celui de l’inflammation chronique.']])) ,
('Le diagnostic associe symptômes et biopsies compatibles. Les {critères histologiques} doivent être interprétés avec le contexte clinique.',paras('Le consensus britannique retient un pic d’au moins 15 éosinophiles par champ à fort grossissement, en précisant la surface de référence du comptage ; il exprime ce seuil par 0,3 mm². La surface des champs varie entre microscopes : ne pas comparer des nombres sans connaître l’unité.', 'Rechercher et discuter les autres causes d’éosinophilie œsophagienne. L’aspect endoscopique peut être normal ; l’histologie demeure nécessaire.', 'Une réponse clinique et histologique à un inhibiteur de la pompe à protons n’exclut pas cette maladie. Un échec préalable d’un tel traitement n’est pas une condition obligatoire du diagnostic.')),
('Les prélèvements doivent tenir compte du caractère inégal de l’inflammation. Les {modalités du bilan} limitent les faux négatifs.',paras('9.a — Référence : endoscopie avec au moins six biopsies œsophagiennes sur au moins deux niveaux, ciblées sur anomalies et zones sans anomalie visible.', '9.b — Rechercher anneaux, sillons, exsudats, œdème et sténose. Une muqueuse d’aspect normal ne dispense pas des prélèvements.', '9.c — Les traitements en cours peuvent atténuer l’infiltrat. Le consensus britannique propose un arrêt des inhibiteurs de la pompe à protons au moins trois semaines avant un bilan diagnostique planifié, sous décision médicale. Ne pas retarder une endoscopie urgente pour ce motif ; si les résultats sont non concluants malgré une forte suspicion, discuter un nouveau bilan adapté.', '9.d — Après traitement, symptômes, endoscopie et biopsies évaluent la réponse : le soulagement seul ne prouve pas la rémission histologique. Les tests allergologiques servent certaines comorbidités, mais ne guident pas seuls les évictions alimentaires de cette maladie.')),
('L’{algorithme de prise en charge} distingue urgence, confirmation et contrôle durable. La composante fibreuse peut nécessiter un geste complémentaire.',steps('Impaction ou complication → traitement urgent et organisation du bilan causal.', 'Dysphagie compatible → endoscopie avec biopsies étagées, même si l’aspect est normal.', 'Maladie confirmée → choisir avec le patient traitement pharmacologique ou régime encadré selon le contexte.', 'Sténose symptomatique → envisager dilatation spécialisée en complément du traitement inflammatoire.', 'Contrôle clinique, endoscopique et histologique → adapter entretien, nutrition et suivi.')),
('Le traitement vise symptômes, inflammation et prévention des récidives. Les {choix thérapeutiques} s’adaptent à l’âge, aux préférences et à la composante sténosante.',paras('11.A — Permettre une alimentation suffisante, réduire les impactions et contrôler l’activité inflammatoire, en tenant compte du retentissement des restrictions alimentaires.', '11.B — Un corticoïde topique avalé est une option. L’information professionnelle suisse du budésonide orodispersible pour l’adulte est reproduite ci-dessous.', '@@MEDICAMENTS@@', 'Les inhibiteurs de la pompe à protons sont aussi utilisés dans les recommandations. L’indication œsophagite à éosinophiles n’est pas décrite dans la fiche Antramups lue pour ce lot : cette utilisation est hors information professionnelle de cette spécialité. Les doses du reflux présentées dans DX.1 ne constituent pas un protocole automatique de cette maladie.', 'Un régime d’éviction empirique peut être proposé avec une diététicienne ou un diététicien expérimenté. Évictions et réintroductions doivent être accompagnées et contrôlées ; ne pas supprimer de nombreux aliments sur la seule base de tests cutanés ou d’anticorps.', 'Une dilatation peut améliorer une dysphagie liée à la fibrose, mais doit être associée au contrôle de l’inflammation. Les formes réfractaires justifient une réévaluation spécialisée et peuvent conduire à discuter d’autres traitements, dont des biothérapies selon indications suisses ; aucun schéma non vérifié n’est proposé ici.', '11.C — Contrôler observance, bonne administration, symptômes, nutrition et réponse endoscopique/histologique. Rechercher candidose et effets systémiques possibles des corticoïdes.', '11.D — L’entretien est souvent nécessaire en raison des récidives après arrêt. Planifier le suivi et, chez l’enfant, la croissance et la transition vers les soins adultes.')),
('La prévention secondaire repose sur le contrôle inflammatoire et le suivi des apports. Les {mesures pratiques} réduisent les retards de prise en charge.',paras('Expliquer les signes d’impaction et la conduite urgente, sans tentative de forcer le passage par de grandes prises alimentaires ou médicamenteuses.', 'Vérifier que l’amélioration n’est pas uniquement due à l’évitement des solides. Suivre nutrition, qualité de vie et restrictions sociales.', 'Ne pas confondre une rémission symptomatique avec une guérison définitive. Les modifications de traitement ou de régime se discutent avec l’équipe et se contrôlent selon le plan spécialisé.')),
('Dysphagie et impactions peuvent révéler une œsophagite à éosinophiles. Une endoscopie normale ne l’exclut pas : biopsies étagées nécessaires. Une réponse aux inhibiteurs de la pompe à protons reste compatible. Dilatation et traitement inflammatoire ont des objectifs complémentaires.', '')
],[('Quels symptômes sont fréquents chez l’adulte ?','Dysphagie et impactions alimentaires.'),('L’absence d’atopie exclut-elle la maladie ?','Non.'),('Que peut masquer une mastication très prolongée ?','Une dysphagie compensée par les habitudes alimentaires.'),('Une muqueuse normale suffit-elle à exclure le diagnostic ?','Non : les biopsies sont nécessaires.'),('Combien de biopsies et de niveaux sont recommandés ici ?','Au moins six biopsies sur au moins deux niveaux œsophagiens.'),('Quel seuil histologique est retenu par le consensus cité ?','Un pic d’au moins 15 éosinophiles par champ à fort grossissement, avec surface de référence précisée, exprimée ici par 0,3 mm².'),('Une réponse à un inhibiteur de la pompe à protons exclut-elle la maladie ?','Non.'),('Faut-il retarder une endoscopie urgente pour attendre un arrêt du traitement ?','Non.'),('Les tests d’allergie choisissent-ils seuls les aliments à éliminer ?','Non : un régime doit être encadré et évalué.'),('La dilatation traite-t-elle l’inflammation ?','Non : elle agit sur la composante obstructive.'),('Peut-on extrapoler automatiquement Jorveza à un enfant ?','Non : la fiche suisse lue ne fournit pas de sécurité et efficacité établies avant 18 ans.'),('Jorveza se prend-il avec une boisson ?','Non : respecter sa désagrégation et l’administration décrites dans l’AIPS.'),('Le soulagement des symptômes suffit-il pour prouver la rémission histologique ?','Non : l’évaluation endoscopique et histologique reste nécessaire selon le suivi.'),('Que faire si un aliment est bloqué et la salive ne passe plus ?','Prise en charge urgente d’une obstruction complète possible.')],(5,6,10,17,18,19),jorveza)
